  '{"definitionId":"played-video-game-mass-effect","slot":1,"id":"historic-quotation/q-d0f7a6a1ea7ee1a30bd4ec1fb6ce6301","text":"Work makes companionship.","person":"Johann Wolfgang von Goethe","personWikipediaUrl":"https://en.wikipedia.org/wiki/Johann_Wolfgang_von_Goethe","sourceTitle":"Maxims and Reflections (T. Bailey Saunders translation)","sourceUrl":"https://www.gutenberg.org/cache/epub/33670/pg33670.txt","sourceSha256":"4ff9b8b40d51e3cd90b2617308afe0c37b92629c4aacefab248b39250460a48f"}',
